#ifndef ZEPHYR_TESTS_SUBSYS_FS_FAT_FS_API_SRC_TEST_FAT_H_
#define ZEPHYR_TESTS_SUBSYS_FS_FAT_FS_API_SRC_TEST_FAT_H_

#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/fs/fs.h>
#include <zephyr/fs/fat_fs.h>
#include <zephyr/storage/disk_access.h>

/*
 * Define DISK_NAME based on the selected disk access type.
 * This macro must expand to a string literal.
 */
#if defined(CONFIG_DISK_ACCESS_RAM)
#define DISK_NAME "RAMDISK"
#elif defined(CONFIG_DISK_ACCESS_SDHC)
#define DISK_NAME CONFIG_SDHC_VOLUME_NAME
#elif defined(CONFIG_DISK_ACCESS_FLASH)
#define DISK_NAME CONFIG_FLASH_AREA_STORAGE_DEV_NAME
#else
/*
 * If no disk access type is selected, this #error will trigger.
 * Ensure one of CONFIG_DISK_ACCESS_RAM, CONFIG_DISK_ACCESS_SDHC,
 * or CONFIG_DISK_ACCESS_FLASH is enabled in the test's Kconfig.
 */
#error "Failed to select DISK access type"
#endif

/* Define the mount point for the FAT file system */
#define TEST_FAT_MOUNT_POINT "/fatfs"

/*
 * Declare the global fs_mount_t structure for the FAT file system.
 * This structure will be defined in common.c.
 */
extern struct fs_mount_t fatfs_mnt;

/*
 * Declare common test helper functions.
 */
void test_fat_mount(void);
void test_fat_unmount(void);
void test_fat_format(void);
void test_fat_setup(void);
void test_fat_teardown(void);

#endif /* ZEPHYR_TESTS_SUBSYS_FS_FAT_FS_API_SRC_TEST_FAT_H_ */
